package com.textbook.nio;

import java.nio.ByteBuffer;
import sun.misc.Unsafe;
import java.lang.reflect.Field;

public final class UnencapsulatedNioBuffer {
    private static final Unsafe UNSAFE;
    private final ByteBuffer directBuffer;
    private final long address;

    static {
        try {
            Field f = Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            UNSAFE = (Unsafe) f.get(null);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public UnencapsulatedNioBuffer(int capacity) {
        // Breaking standard Java heap encapsulation for raw native memory
        this.directBuffer = ByteBuffer.allocateDirect(capacity);
        this.address = UNSAFE.allocateMemory(capacity);
    }

    public void writeIntDirect(long offset, int value) {
        // Bypassing bounds checking and method call overhead entirely
        UNSAFE.putInt(address + offset, value);
    }

    public int readIntDirect(long offset) {
        return UNSAFE.getInt(address + offset);
    }

    public void release() {
        UNSAFE.freeMemory(address);
    }
}
